import{_ as t,o,c as a,ag as r}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Specify · Delegate · Verify, and the Safe Loop","description":"","frontmatter":{"source":"resources/safe-loop.md"},"headers":[],"relativePath":"resources/safe-loop.md","filePath":"resources/safe-loop.md"}'),s={name:"resources/safe-loop.md"};function n(i,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="specify--delegate--verify-and-the-safe-loop" tabindex="-1">Specify · Delegate · Verify, and the Safe Loop <a class="header-anchor" href="#specify--delegate--verify-and-the-safe-loop" aria-label="Permalink to &quot;Specify · Delegate · Verify, and the Safe Loop&quot;">​</a></h1><blockquote><p>The course&#39;s core triad, the inner loop that carries it out, and how a team runs both on a shared codebase. One page; keep it open in every Lab.</p></blockquote><p><strong>Credit.</strong> The Safe Loop, check first and the two-strikes rule come from this course&#39;s lower-division sibling, <em>Building Apps with AI</em> (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/resources/safe-loop.html" target="_blank" rel="noreferrer">its Safe Loop page</a>), where students meet them as beginners. The triad is UT Austin CS 378&#39;s framing of agentic work as &quot;what you specify, what you delegate, and what you verify&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>). The observed/inferred tags come from Stanford CS146S.</p><h2 id="specify--delegate--verify" tabindex="-1">Specify · Delegate · Verify <a class="header-anchor" href="#specify--delegate--verify" aria-label="Permalink to &quot;Specify · Delegate · Verify&quot;">​</a></h2><p>Decide all three <strong>before</strong> an agent touches the code, and write them in the task (<a href="./../templates/TASKS.html">TASKS.md template</a>).</p><table tabindex="0"><thead><tr><th></th><th>The question</th><th>The artifact</th><th>It&#39;s done when</th></tr></thead><tbody><tr><td><strong>Specify</strong></td><td>What must be true when this is finished, including the edge cases and what is out of scope?</td><td>Acceptance criteria in <code>SPEC.md</code> (WHEN … THE SYSTEM SHALL …); design decisions in <code>DESIGN.md</code></td><td>A fresh agent session could build it from the document alone (the <a href="./agent-patterns.html#the-goldfish-test">Goldfish test</a>)</td></tr><tr><td><strong>Delegate</strong></td><td>Which part goes to an agent, which agent, with what context, what permissions and what budget? Which part do you keep?</td><td>A task in <code>TASKS.md</code>: files in scope, commands allowed, step limit</td><td>The task fits in one session and one small diff</td></tr><tr><td><strong>Verify</strong></td><td>How will you know it&#39;s right, by evidence you can show?</td><td>Tests written before the code; a mutation score; a review; a security check; a reproducible command</td><td>Every claim in your PR is tagged <strong>observed</strong></td></tr></tbody></table><p><strong>What not to delegate.</strong> The specification itself (as Michigan&#39;s EECS 498 puts it, &quot;a one-shot prompt gives you the model&#39;s design, not yours&quot;: <a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03</a>), the tests that define &quot;correct&quot; (written in a separate session, or by you), security decisions, and anything you couldn&#39;t explain afterwards.</p><p><strong>A worked example (week 5).</strong> <em>Specify:</em> <code>roomly</code> recurring bookings, criteria R1–R9, including a weekly series that crosses a daylight-saving change. <em>Delegate:</em> the expansion of a series into occurrences, to a CLI agent, in plan mode, <code>src/recurrence.js</code> and its test file only. <em>Verify:</em> property tests written first (&quot;no generated occurrence overlaps an existing booking&quot;), then the mutation score of the new module, then your own read of the diff.</p><h2 id="the-safe-loop" tabindex="-1">The Safe Loop <a class="header-anchor" href="#the-safe-loop" aria-label="Permalink to &quot;The Safe Loop&quot;">​</a></h2><p>The inner loop for every change. After step 6, go back to step 1 for the next small change.</p><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>What a senior does</th></tr></thead><tbody><tr><td>1</td><td><strong>Describe</strong></td><td>State the goal, context, constraints and &quot;done when&quot;. Then <strong>check first</strong>: write the check that proves it, in a separate prompt or by hand, before asking for code</td></tr><tr><td>2</td><td><strong>Plan</strong></td><td>Ask for a plan, in plan mode or with &quot;don&#39;t edit anything yet&quot;. Edit the plan; reject steps that touch files outside the task</td></tr><tr><td>3</td><td><strong>Step</strong></td><td>Approve <strong>one</strong> step. Approvals stay on (<a href="./../setup/safety-contract.html#2-approvals-stay-on">rule 2</a>)</td></tr><tr><td>4</td><td><strong>Test</strong></td><td>Run the check, the suite, and one edge case yourself. Read the output; don&#39;t accept the agent&#39;s summary of it</td></tr><tr><td>5</td><td><strong>Read</strong></td><td>Read the whole diff. Keep only what you can explain line by line. Look for tests that were weakened, skipped or edited to match the code</td></tr><tr><td>6</td><td><strong>Commit</strong></td><td>A message that says what changed, and <code>Assisted-by: [tool and model]</code> if AI helped. Log the session in <code>AI_LOG.md</code></td></tr></tbody></table><p><strong>Check first.</strong> Tests generated after faulty code caught 14% of its faults, against 25% for tests generated independently (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>), and LLM-generated oracles tend to encode what the code does rather than what it should do (<a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">Konstantinou, Degiovanni &amp; Papadakis</a>). So the test-writer gets the criterion and the function&#39;s signature, not the implementation. Run the test before the code exists: it should fail. <strong>Never let an agent change a test to make it pass</strong>; if a test seems wrong, decide yourself and say why in the commit.</p><p><strong>The two-strikes rule.</strong> If two attempts to fix the same problem fail: stop; go back to the last good commit if things got worse; start a fresh session; rewrite the task with what you learned (what you tried, the exact error, what you expected). Long, muddled sessions make agents worse (<a href="./glossary.html#context-rot">context rot</a>).</p><p><strong>Observed and inferred.</strong> Every claim you make about the codebase, the agent or a tool, in a report, a PR or an oral exam, is one or the other. &quot;The agent said the tests pass&quot; is inferred. &quot;<code>npm test</code>: 48 passing, 0 failing, at commit <code>a1b2c3d</code>&quot; is observed.</p><h2 id="the-safe-loop-for-teams" tabindex="-1">The Safe Loop for teams <a class="header-anchor" href="#the-safe-loop-for-teams" aria-label="Permalink to &quot;The Safe Loop for teams&quot;">​</a></h2><p>On a shared codebase the loop is the same, but the steps belong to different people, and the commit becomes a pull request.</p><table tabindex="0"><thead><tr><th>Loop step</th><th>Team version</th><th>Who</th></tr></thead><tbody><tr><td>Describe</td><td>An issue with acceptance criteria, linked to <code>SPEC.md</code>; Specify · Delegate · Verify filled in</td><td>The issue&#39;s owner</td></tr><tr><td>Check first</td><td>Tests (or a failing reproduction) committed on the branch before the implementation</td><td>The owner, or a teammate who didn&#39;t write the code</td></tr><tr><td>Plan</td><td>The plan posted on the issue or in the PR draft, so a teammate can object early</td><td>The owner</td></tr><tr><td>Step</td><td>One task per branch or <a href="./agent-patterns.html#worktrees">worktree</a>, one agent per task</td><td>The owner as agent operator</td></tr><tr><td>Test</td><td>CI runs tests, lint and static analysis on every push; the owner runs the edge cases CI can&#39;t</td><td>CI and the owner</td></tr><tr><td>Read</td><td><strong>Review by a teammate who didn&#39;t operate the agent.</strong> An AI reviewer may comment too, but a human approves</td><td>A teammate (<a href="./../templates/REVIEW.html">REVIEW.md template</a>)</td></tr><tr><td>Commit</td><td>Merge through a PR whose description the owner wrote (🔴 AI off) and whose AI section is filled in (<a href="./../templates/PULL_REQUEST_TEMPLATE.html">template</a>)</td><td>The owner</td></tr></tbody></table><p><strong>Rules that make it work.</strong></p><ul><li><strong>The author doesn&#39;t review their own PR, and neither does their agent.</strong> Agent PRs that are merged often need follow-up: 45.1% of merged Claude Code PRs in one study needed further changes, mostly bug fixes, docs and project conventions (<a href="https://arxiv.org/abs/2509.14745" target="_blank" rel="noreferrer">Watanabe et al.</a>).</li><li><strong>Small PRs.</strong> Review burden is the bottleneck, not generation. Students in courses that send PRs upstream are told the same thing (&quot;make smaller PRs&quot;: <a href="https://blog.humphd.org/teaching-open-source-fall-2021/" target="_blank" rel="noreferrer">Seneca OSD600</a>).</li><li><strong>Name the merge point before you parallelize.</strong> UT Austin&#39;s rule: &quot;Parallelize a task once you can name its merge point&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/schedule.html" target="_blank" rel="noreferrer">CS 378 schedule</a>). Two agents editing the same module is a merge conflict you scheduled.</li><li><strong>One operator per agent session.</strong> Whoever approved the agent&#39;s commands answers for them in review and in the oral exam: &quot;if you can&#39;t explain it, you didn&#39;t build it&quot; (Michigan&#39;s rule, <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">EECS 498</a>).</li><li><strong>Process is the evidence.</strong> Grading uses the commit history, <code>AI_LOG.md</code>, the tests and the PR thread, not the number of features (<a href="./../assessment/">assessment</a>).</li></ul><h2 id="when-the-loop-says-stop" tabindex="-1">When the loop says stop <a class="header-anchor" href="#when-the-loop-says-stop" aria-label="Permalink to &quot;When the loop says stop&quot;">​</a></h2><ul><li>The agent wants to edit files outside the task, install something you didn&#39;t plan, or change its own configuration.</li><li>A test you didn&#39;t write changed in the diff.</li><li>You can&#39;t explain a line, and the agent&#39;s explanation doesn&#39;t match the code.</li><li>The second fix failed (two strikes).</li><li>The task turned out to need a design decision. Go back to <em>Specify</em>.</li></ul><p>More patterns for the Delegate step: <a href="./agent-patterns.html">Agent Patterns</a>.</p>',22)])])}const f=t(s,[["render",n]]);export{g as __pageData,f as default};
